import{_ as t,o as d,c as o,ae as r}from"./chunks/framework.YL6nI5ZP.js";const h=JSON.parse('{"title":"Cómo Ejecutar los Scripts, Benchmarks y Harnesses de Verificación","description":"","frontmatter":{},"headers":[],"relativePath":"es/how-to/04-scripts-y-benchmarks.md","filePath":"es/how-to/04-scripts-y-benchmarks.md"}'),a={name:"es/how-to/04-scripts-y-benchmarks.md"};function s(c,e,n,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="como-ejecutar-los-scripts-benchmarks-y-harnesses-de-verificacion" tabindex="-1">Cómo Ejecutar los Scripts, Benchmarks y Harnesses de Verificación <a class="header-anchor" href="#como-ejecutar-los-scripts-benchmarks-y-harnesses-de-verificacion" aria-label="Permalink to &quot;Cómo Ejecutar los Scripts, Benchmarks y Harnesses de Verificación&quot;">​</a></h1><p>Ejecuta los benchmarks basados en Node, las sondas, los generadores de entrada y los harnesses de extremo a extremo Chrome/CDP que verifican el motor.</p><p>Todo se ejecuta desde la raíz del repo con <code>node scripts/&lt;nombre&gt;.mjs</code>. El patrón común: shim <code>globalThis.self/window</code>, cargar <code>public/openswmm2d.js</code>, instanciar <code>openswmm2d.wasm</code> sincrónicamente en Node, envolver la API C con <code>Module.cwrap</code>. Varios lanzan <code>server.py</code> + una instancia de Chrome vía CDP.</p><h2 id="_1-benchmarks-y-sondas-motor-en-node" tabindex="-1">1. Benchmarks y sondas (motor en Node) <a class="header-anchor" href="#_1-benchmarks-y-sondas-motor-en-node" aria-label="Permalink to &quot;1. Benchmarks y sondas (motor en Node)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Uso</th></tr></thead><tbody><tr><td><code>bench-1d-bellinge.mjs</code></td><td>Costos por-stride / por-window / freeze / cplF en Bellinge; proyecta 48 h de tiempo de pared</td><td>sin argumentos</td></tr><tr><td><code>bench-1d.mjs</code></td><td>Benchmark de stride 1D puro; salida JSON</td><td><code>node bench-1d.mjs &lt;inp&gt; [--wasm &lt;ruta&gt;] [--tag &lt;l&gt;] [--keep-vs]</code></td></tr><tr><td><code>probe-1d.mjs</code></td><td>Volcado de altura/depths de nodo por paso (máx. 80 pasos)</td><td><code>node probe-1d.mjs &lt;inp&gt;</code></td></tr><tr><td><code>probe-1d-coupl.mjs</code></td><td>Carga 1D tipo split: <code>setPondArea</code> + <code>setLatInflow</code> alternados; histograma de dt</td><td>sin argumentos (fixture de Bellinge)</td></tr><tr><td><code>probe-1d-nan.mjs</code></td><td>Corrida 1D completa de 48 h escaneando alturas/depths/volúmenes en busca de NaN/Inf</td><td><code>node probe-1d-nan.mjs [VS]</code></td></tr><tr><td><code>probe-cpl.mjs</code></td><td>Deltas de volumen de acoplamiento por stride desde el buffer de balance de masa de 10 ranuras</td><td><code>node probe-cpl.mjs &lt;inp&gt;</code></td></tr><tr><td><code>run-engine-marcher.mjs</code></td><td>Corrida 2D de referencia: depth/velocidad/altura por frame + alturas de nodo + balance de masa → JSON. Requiere un build de wasm <strong>sin threads</strong> (el build con threads necesita un navegador)</td><td><code>node run-engine-marcher.mjs &lt;inp&gt; &lt;out.json&gt; [--frames N] [--interval &lt;seg&gt;] [--wasm &lt;p&gt;]</code></td></tr><tr><td><code>bench-wasm-threads.mjs</code></td><td><strong>Compuerta del motor con threads:</strong> ejecuta el <code>openSwmm2dWorker.js</code> de producción en Chrome aislado de origen cruzado con THREADS 1 vs N; reporta tiempo de pared + continuidad bit idéntica</td><td>CDP 9225</td></tr></tbody></table><h2 id="_2-generadores-de-entrada-sintetica" tabindex="-1">2. Generadores de entrada sintética <a class="header-anchor" href="#_2-generadores-de-entrada-sintetica" aria-label="Permalink to &quot;2. Generadores de entrada sintética&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Uso</th></tr></thead><tbody><tr><td><code>make-marcher-inp.mjs</code></td><td>INP 2D de cuenca cerrada M1 (bordes WALL, lecho sinusoidal)</td><td><code>node make-marcher-inp.mjs &lt;nx&gt; &lt;ny&gt; &lt;dx&gt; &lt;rainMmHr&gt; &lt;min&gt; &lt;out.inp&gt;</code></td></tr><tr><td><code>make-marcher-cpl-inp.mjs</code></td><td>INP de acoplamiento 1D↔2D M2 (storage S1 + conducto + outfall, celda 0 acoplada)</td><td><code>node make-marcher-cpl-inp.mjs &lt;out.inp&gt;</code></td></tr></tbody></table><h2 id="_3-harnesses-de-extremo-a-extremo-chrome-cdp" tabindex="-1">3. Harnesses de extremo a extremo Chrome/CDP <a class="header-anchor" href="#_3-harnesses-de-extremo-a-extremo-chrome-cdp" aria-label="Permalink to &quot;3. Harnesses de extremo a extremo Chrome/CDP&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Script</th><th>Propósito</th><th>Puerto</th><th>Uso</th></tr></thead><tbody><tr><td><code>verify-bellinge.mjs</code></td><td><strong>Compuerta insignia:</strong> Chrome headless carga la app, proyecta Bellinge a EPSG:25832, auto-carga <code>Bellinge2.tif</code>, genera la malla, ejecuta el modelo completo de 48 h a través del propio worker de la app, verifica frames/depths/balance de masa/continuidad</td><td>CDP 9222</td><td>sin argumentos; escribe <code>scripts/verify-out/</code></td></tr><tr><td><code>verify-1d-split.mjs</code></td><td>Compuerta de regresión para la pierna 1D del split (usa el <code>couplingSplit.js</code> de producción; falla con alturas de acoplamiento no finitas)</td><td>—</td><td><code>node verify-1d-split.mjs &lt;inp&gt; [--wasm &lt;p&gt;] [--tol &lt;%&gt;] [--hours &lt;n&gt;] [--json]</code></td></tr><tr><td><code>test-gpu-worker.mjs</code></td><td>Conduce el <code>gpu2dWorker.js</code> de producción a través del contrato <code>run2d</code> de la app en Chrome con ventana</td><td>CDP 9224</td><td><code>node test-gpu-worker.mjs [--inp &lt;p&gt;]</code></td></tr><tr><td><code>bench-gpu-coupl.mjs</code></td><td>Tiempos del split de GPU por window (<code>strideMs/freezeMs/advanceMs/exchMs/dt0/substeps</code>), extrapola 48 h de tiempo de pared</td><td>CDP 9225</td><td><code>node bench-gpu-coupl.mjs [--windows N] [--lts N] [--cadence N] [--dtfloor N] [--dbgcell N] [--inp &lt;p&gt;]</code></td></tr><tr><td><code>run-webgpu-harness.mjs</code></td><td>Conduce <code>public/webgpu/harness.html</code> M1/M2 paridad + bench en Chrome <strong>con ventana</strong> (headless no tiene WebGPU); prepara fixtures en <code>public/webgpu/fixtures/</code> desde <code>scripts/verify-out/</code></td><td>CDP 9223</td><td><code>node run-webgpu-harness.mjs [fixture…] [--coupled] [--bench] [--lts N] [--hours N]</code></td></tr><tr><td><code>test-2d-render.mjs</code></td><td>Prueba de humo del pipeline de render: flechas de velocidad, regresión de bandas de contorno, frame-max robusto, compilación de shaders WebGL2, finitud de <code>display2DResults</code></td><td>CDP 9225</td><td>sin argumentos</td></tr></tbody></table><blockquote><p><strong>Nota:</strong> <code>public/webgpu/fixtures/</code> <strong>no está commiteado</strong> — los scripts del harness lo generan/preparan desde <code>scripts/verify-out/</code>. Si falta un fixture, ejecuta primero el generador (<code>make-marcher-*.mjs</code>) o <code>verify-bellinge.mjs</code>.</p></blockquote>',10)])])}const u=t(a,[["render",s]]);export{h as __pageData,u as default};
